-- Просто дата без точного времени
ALTER TABLE PERSON ADD COLUMN date_of_birth DATE;
-- Точное время
-- Значение timestamp сохраняется в секундах до или после полуночи
ALTER TABLE PERSON ADD COLUMN created_at timestamp;